-- ============================================================================
-- AAS capability matching, step 1: load the RFQ and the offers, audit them
-- ============================================================================
-- Kröger Verpackungstechnik needs a servo drive for the Y axis of a tray sealer.
-- The RFQ is an Asset Administration Shell with IDTA-02020 Required
-- capabilities; four suppliers answer with AAS: JSON, XML and an AASX package.
-- Before ranking, the buyer checks what cannot be compared.
--
-- Data: examples/aas_capability_matching/data (generated by
--   cd scripts && uv run python -m scripts.examples.aas_capability_matching)
-- Run:  DATAZOO_DISABLE_TELEMETRY=1 ./build/release/duckdb < examples/aas_capability_matching/01_load_and_audit.sql
-- ============================================================================

.print '>>> 1. Audit first: aas_issues never fails, so a broken file shows up with its name'
SELECT split_part(filename, '/', -1) AS file, i.issue, i.severity,
       split_part(regexp_replace(i.path, '\.Property(Property|Range)$', ''), '.', -1) AS property
FROM (SELECT filename, unnest(aas_issues(content, NULL, (SELECT list(u) FROM read_csv('examples/aas_capability_matching/data/eclass_units.csv') u))) AS i
      FROM read_blob('examples/aas_capability_matching/data/offers/*'))
ORDER BY file, i.issue;
-- Expected:
-- | file                 | issue                       | severity | property           |
-- | kessler_ksd10.aasx   | bad_value                   | warning  | CycleTime          |
-- | kessler_ksd10.aasx   | missing_concept_description | warning  | AmbientTemperature |
-- | orbitec_ox6.aas.json | decimal_comma               | info     | RatedCurrent       |
-- | orbitec_ox6.aas.json | unknown_unit_id             | warning  | RatedCurrent       |

.read examples/aas_capability_matching/sql/load.sql

.print ''
.print '>>> 2. What arrived: one tree per shell, capabilities as items'
SELECT file, count(*) FILTER (node_kind = 'item') AS items,
       (SELECT count(*) FROM tree_attributes a WHERE a.tree_id = n.tree_id) AS properties
FROM tree_nodes n GROUP BY file, tree_id ORDER BY file;
-- Expected:
-- | file                  | items | properties |
-- | driventa_ds12.aas.xml | 2     | 6          |
-- | kessler_ksd10.aasx    | 2     | 6          |
-- | lenvaro_lx8.aas.json  | 3     | 9          |
-- | orbitec_ox6.aas.json  | 3     | 8          |
-- | rfq_2026_117.aas.json | 2     | 6          |

.print ''
.print '>>> 3. The requirements as the kernel reads them: dictionary key, base units, bound'
SELECT attr_id, attr_key, lo, hi, unit, bound, category
FROM tree_attributes WHERE tree_id = 'RFQ-2026-117' ORDER BY attr_id;
-- Expected:
-- | attr_id            | attr_key             | lo     | hi     | unit | bound    | category         |
-- | AmbientTemperature | 0173-1#02-BAA039#012 | 318.15 | 318.15 | K    | at_least | NULL             |
-- | CycleTime          | 0173-1#02-AAZ901#002 | 0.001  | 0.001  | s    | at_most  | NULL             |
-- | Protocol           | 0173-1#02-AAZ902#002 | NULL   | NULL   | NULL | NULL     | 0173-1#07-AAZ001 |
-- | RatedCurrent       | 0173-1#02-BAA120#008 | 7.6    | 7.6    | A    | at_least | NULL             |
-- | SafeTorqueOff      | 0173-1#02-AAZ903#001 | NULL   | NULL   | NULL | NULL     | true             |
-- | SupplyVoltage      | 0173-1#02-AAB381#005 | 380.0  | 480.0  | V    | within   | NULL             |

.print ''
.print '>>> 4. validate_trees: the one value without a unit'
SELECT tree_id, attr_id, issue FROM validate_trees('tree_nodes', 'tree_attributes');
-- Expected:
-- | tree_id                                     | attr_id            | issue        |
-- | https://kessler-antriebe.example/aas/ksd-10 | AmbientTemperature | unknown_unit |

.print ''
.print '>>> 5. Data quality per submodel'
SELECT split_part(filename, '/', -1) AS file, q.submodel, round(q.semantic_id_share, 2) AS coded,
       q.n_missing_concept_description AS no_dictionary, q.n_unparseable AS unparseable, q.n_mixed_releases AS mixed_releases
FROM (SELECT filename, unnest(aas_quality(content)) AS q FROM read_blob('examples/aas_capability_matching/data/offers/*'))
ORDER BY file, q.submodel;
-- Expected:
-- | file                  | submodel              | coded | no_dictionary | unparseable | mixed_releases |
-- | driventa_ds12.aas.xml | CapabilityDescription | 1.0   | 0             | 0           | 0              |
-- | kessler_ksd10.aasx    | CapabilityDescription | 1.0   | 1             | 1           | 0              |
-- | lenvaro_lx8.aas.json  | CapabilityDescription | 1.0   | 0             | 0           | 1              |
-- | lenvaro_lx8.aas.json  | TechnicalData         | 1.0   | 0             | 0           | 1              |
-- | orbitec_ox6.aas.json  | CapabilityDescription | 1.0   | 0             | 0           | 0              |
-- | orbitec_ox6.aas.json  | TechnicalData         | 1.0   | 0             | 0           | 0              |
